SELECT *, AVG(amount) OVER (PARTITION BY status) AS status_avg_amount, MAX(amount) OVER (PARTITION BY status ORDER BY CAST(paid_at AS BIGINT) ASC RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS amount_max_7d, NTILE(4) OVER (PARTITION BY order_id, status ORDER BY amount DESC, id ASC) AS amount_bucket, NTILE(3) OVER (PARTITION BY order_id, method ORDER BY amount ASC, id ASC) AS amount_bucket_2 FROM payments;
